function prefixToPostfix(s) {
  const items = s.split("").map((c) => ({ text: c, op: "+-*/^".includes(c) }));
  while (items.length > 1) {
    for (let i = 0; i + 2 < items.length; i++) {
      // an operator followed by two finished operands is an innermost operation
      if (items[i].op && !items[i + 1].op && !items[i + 2].op) {
        const piece = items[i + 1].text + items[i + 2].text + items[i].text;
        items.splice(i, 3, { text: piece, op: false });   // the piece is an operand now
        break;                                            // the list changed: start over
      }
    }
  }
  return items[0].text;
}

