String prefixToPostfix(String s) {
    List<String> text = new ArrayList<>();       // each item's text
    List<Boolean> isOp = new ArrayList<>();      // and whether it's a bare operator
    for (char c : s.toCharArray()) {
        text.add(String.valueOf(c));
        isOp.add("+-*/^".indexOf(c) >= 0);
    }
    while (text.size() > 1) {
        for (int i = 0; i + 2 < text.size(); i++) {
            // an operator followed by two finished operands is an innermost operation
            if (isOp.get(i) && !isOp.get(i + 1) && !isOp.get(i + 2)) {
                String piece = text.get(i + 1) + text.get(i + 2) + text.get(i);
                text.subList(i, i + 3).clear();
                isOp.subList(i, i + 3).clear();
                text.add(i, piece);
                isOp.add(i, false);              // the piece is an operand now
                break;                           // the list changed: start over
            }
        }
    }
    return text.get(0);
}

string prefixToPostfix(const string& s) {
    vector<pair<string, bool>> items;          // (text, is it a bare operator?)
    for (char c : s) items.push_back({string(1, c), string("+-*/^").find(c) != string::npos});
    while (items.size() > 1) {
        for (size_t i = 0; i + 2 < items.size(); i++) {
            // an operator followed by two finished operands is an innermost operation
            if (items[i].second && !items[i + 1].second && !items[i + 2].second) {
                string piece = items[i + 1].first + items[i + 2].first + items[i].first;
                items.erase(items.begin() + i, items.begin() + i + 3);
                items.insert(items.begin() + i, make_pair(piece, false));   // the piece is an operand now
                break;                                              // the list changed: start over
            }
        }
    }
    return items[0].first;
}

function prefixToPostfix(s) {
  let i = 0;                                 // the next character to read
  function build() {
    const c = s[i++];
    if (!"+-*/^".includes(c)) return c;      // an operand is complete on its own
    const left = build();                    // the operator's first operand...
    const right = build();                   // ...then its second
    return left + right + c;                 // the operator goes last
  }
  return build();
}

