}

string build(const string& s, int& i) {
    char c = s[i++];
    if (string("+-*/^").find(c) == string::npos) return string(1, c);   // an operand is complete on its own
    string left = build(s, i);               // the operator's first operand...
    string right = build(s, i);              // ...then its second
    return left + right + c;                 // the operator goes last
}

string prefixToPostfix(const string& s) {
    int i = 0;                               // the next character to read
    return build(s, i);
}

function prefixToPostfix(s) {
  const stack = [];
  for (let i = s.length - 1; i >= 0; i--) {     // read right to left
    const c = s[i];
    if ("+-*/^".includes(c)) {
      const left = stack.pop();
      const right = stack.pop();
      stack.push(left + right + c);               // the operator goes last
    } else {
      stack.push(c);                              // an operand
    }
  }
  return stack.pop();
}

