String prefixToPostfix(String s) {
    Deque<String> stack = new ArrayDeque<>();
    for (int i = s.length() - 1; i >= 0; i--) {  // read right to left
        char c = s.charAt(i);
        if ("+-*/^".indexOf(c) >= 0) {
            String left = stack.pop();
            String right = stack.pop();
            stack.push(left + right + c);        // the operator goes last
        } else {
            stack.push(String.valueOf(c));       // an operand
        }
    }
    return stack.pop();
}

string prefixToPostfix(const string& s) {
    stack<string> st;
    for (int i = (int)s.size() - 1; i >= 0; i--) {   // read right to left
        char c = s[i];
        if (string("+-*/^").find(c) != string::npos) {
            string left = st.top(); st.pop();
            string right = st.top(); st.pop();
            st.push(left + right + c);               // the operator goes last
        } else {
            st.push(string(1, c));                   // an operand
        }
    }
    return st.top();
}
